package com.richfield.smartpantry;
import android.content.*;import android.os.*;import android.widget.*;
public class SettingsActivity extends BaseActivity{@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=page("Settings");TextView t=new TextView(this);t.setText("Choose how Smart Pantry helps you manage leftovers.");t.setTextSize(16);r.addView(t);Switch alerts=new Switch(this);alerts.setText("Expiring-soon alerts");alerts.setTextSize(18);boolean on=getSharedPreferences("settings",0).getBoolean("alerts",true);alerts.setChecked(on);alerts.setOnCheckedChangeListener((v,checked)->getSharedPreferences("settings",0).edit().putBoolean("alerts",checked).apply());r.addView(alerts);TextView info=new TextView(this);info.setText("\nPantry data is stored locally on this device using SQLite. Recipe suggestions use strict matching: every required ingredient must be present in a sufficient quantity.");info.setTextSize(16);r.addView(info,new LinearLayout.LayoutParams(-1,0,1));nav(r);setContentView(r);}}
